<template><nav class="tabs"><button v-for="item in items" :key="item.key||item.label||item" :class="{active:current===(item.key||item.label||item)}" type="button" @click="select(item.key||item.label||item)">{{item.label||item}}</button></nav></template>
<script setup>import{computed}from'vue';const props=defineProps({items:{type:Array,default:()=>[]},modelValue:{type:[String,Number],default:''}});const emit=defineEmits(['update:modelValue','change']);const current=computed(()=>props.modelValue||props.items[0]?.key||props.items[0]?.label||props.items[0]||'');function select(v){emit('update:modelValue',v);emit('change',v)}</script>
<style scoped>.tabs{width:343px;height:42px;display:flex;border-bottom:1px solid #E5E6EB}.tabs button{position:relative;flex:1;height:42px;padding:0 8px;border:0;color:#86909C;background:transparent;font:400 14px/22px "PingFang SC",sans-serif}.tabs button.active{color:#00AAA6;font-weight:600}.tabs button.active:after{content:'';position:absolute;bottom:-1px;left:50%;width:40px;height:2px;transform:translateX(-50%);background:#00AAA6}</style>
